import itertools

def outcome_of(perm,A):
    n=len(perm)
    S=set(range(n))
    for k in A:
        S={i for i in S if i==k or (i-k)*(perm[i]-perm[k])<0}
    return tuple(sorted(S))

def antichains(perm):
    n=len(perm)
    idx=range(n)
    res=[]
    for r in range(n+1):
        for A in itertools.combinations(idx,r):
            ok=True
            for i in range(r):
                for j in range(i+1,r):
                    a,b=A[i],A[j]
                    if (a-b)*(perm[a]-perm[b])>0:
                        ok=False
            if ok: res.append(A)
    return res

for n in range(1,9):
    bad=0
    for perm in itertools.permutations(range(1,n+1)):
        AC=antichains(perm)
        mp={}
