import sys
sys.setrecursionlimit(1_000_000)

MOD = 998244353

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    A = [x - 1 for x in map(int, input().split())]

    # Reverse graph for Kosaraju
    rev = [[] for _ in range(N)]
    for i, to in enumerate(A):
        rev[to].append(i)

    vis = [False] * N
    order = []

    def dfs1(v):
        vis[v] = True
        to = A[v]
        if not vis[to]:
            dfs1(to)
        order.append(v)

    for v in range(N):
        if not vis[v]:
            dfs1(v)

    comp = [-1] * N

    def dfs2(v, cid):
        comp[v] = cid
        for u in rev[v]:
            if comp[u] == -1:
                dfs2(u, cid)

    cid = 0
    for v in reversed(order):
        if comp[v] == -1:
            dfs2(v, cid)
            cid += 1

    K = cid

    # Build forest of SCCs: child -> parent (because x_child <= x_parent)
    parent = [-1] * K
    for v in range(N):
        cv = comp[v]
        cu = comp[A[v]]
        if cv != cu:
            parent[cv] = cu

    children = [[] for _ in range(K)]
    roots = []
    for u in range(K):
        p = parent[u]
        if p == -1:
            roots.append(u)
        else:
            children[p].append(u)

    def solve_subtree(u):
        # F[t] = number of assignments in subtree(u) with value(u) = t
        F = [1] * (M + 1)
        for c in children[u]:
            Fc = solve_subtree(c)
            s = 0
            for t in range(1, M + 1):
                s += Fc[t]
                if s >= MOD:
                    s -= MOD
                F[t] = (F[t] * s) % MOD
        return F

    ans = 1
    for r in roots:
        Fr = solve_subtree(r)
        total = sum(Fr[1:]) % MOD
        ans = (ans * total) % MOD

    print(ans)

if __name__ == "__main__":
    main()

