import sys

MOD = 998244353


def sieve(n=1000):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    primes = []
    for i in range(2, n + 1):
        if is_prime[i]:
            primes.append(i)
            if i * i <= n:
                for j in range(i * i, n + 1, i):
                    is_prime[j] = False
    return primes


def main():
    input = sys.stdin.readline
    N = int(input().strip())
    A = list(map(int, input().split()))

    primes = sieve(1000)

    # Only keep primes that actually appear.
    exp_map = {}  # p -> list length N-1
    for i, x0 in enumerate(A):
        x = x0
        for p in primes:
            if p * p > x:
                break
            if x % p == 0:
                c = 0
                while x % p == 0:
                    x //= p
                    c += 1
                if p not in exp_map:
                    exp_map[p] = [0] * (N - 1)
                exp_map[p][i] = c
        if x > 1:
            if x not in exp_map:
                exp_map[x] = [0] * (N - 1)
            exp_map[x][i] += 1

    ans = 1

    for p, exps in exp_map.items():
        D = sum(exps)
        if D == 0:
            continue

        maxH = 2 * D

        # p^h for h=0..maxH
        pows = [1] * (maxH + 1)
        for h in range(1, maxH + 1):
            pows[h] = (pows[h - 1] * p) % MOD

        # DP over current exponent height h.
        # nohit[h]: weighted count where 0 has not appeared yet
        # hit[h]  : weighted count where 0 has appeared at least once
        nohit = [0] * (maxH + 1)
        hit = [0] * (maxH + 1)

        # Initial S_1 exponent can be 0..D (larger cannot ever reach 0).
        hit[0] = 1  # weight p^0
        for h in range(1, D + 1):
            nohit[h] = pows[h]  # includes contribution of S_1

        hi = D  # current reachable maximum height

        for a in exps:
            n_nohit = [0] * (maxH + 1)
            n_hit = [0] * (maxH + 1)

            if a == 0:
                # deterministic: h -> h, and multiply by p^h (for next term)
                for h in range(hi + 1):
                    mult = pows[h]
                    v0 = nohit[h]
                    if v0:
                        n_nohit[h] = (n_nohit[h] + v0 * mult) % MOD
                    v1 = hit[h]
                    if v1:
                        n_hit[h] = (n_hit[h] + v1 * mult) % MOD
            else:
                new_hi = min(maxH, hi + a)
                for h in range(hi + 1):
                    v0 = nohit[h]
                    v1 = hit[h]
                    if not v0 and not v1:
                        continue

                    # Move up: h -> h+a
                    h2 = h + a
                    if h2 <= maxH:
                        mult = pows[h2]
                        if v0:
                            n_nohit[h2] = (n_nohit[h2] + v0 * mult) % MOD
                        if v1:
                            n_hit[h2] = (n_hit[h2] + v1 * mult) % MOD

                    # Move down: h -> h-a (if possible)
                    if h >= a:
                        h2 = h - a
                        mult = pows[h2]
                        if v0:
                            if h2 == 0:
                                n_hit[0] = (n_hit[0] + v0 * mult) % MOD
                            else:
                                n_nohit[h2] = (n_nohit[h2] + v0 * mult) % MOD
                        if v1:
                            n_hit[h2] = (n_hit[h2] + v1 * mult) % MOD

                hi = new_hi

            nohit, hit = n_nohit, n_hit

        Fp = sum(hit) % MOD
        ans = (ans * Fp) % MOD

    print(ans)


if __name__ == "__main__":
    main()

