from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        by_right = [[] for _ in range(n + 1)]

        for i, (x, y) in enumerate(conflictingPairs):
            a, b = (x, y) if x < y else (y, x)
            by_right[b].append((a, i))

        gain = [0] * m

        # Among all processed pairs (with right endpoint <= current r):
        # v1 = largest left endpoint value, c1 = number of pairs achieving v1,
        # uid = pair id if c1 == 1, v2 = second largest distinct left endpoint value.
        v1 = 0
        c1 = 0
        uid = -1
        v2 = 0

        base = 0

        for r in range(1, n + 1):
            for a, i in by_right[r]:
                if a > v1:
                    v2 = v1
                    v1 = a
                    c1 = 1
                    uid = i
                elif a == v1:
                    c1 += 1
                elif a > v2:
                    v2 = a

            base += r - v1

            if c1 == 1 and uid != -1:
                gain[uid] += v1 - v2

        return base + max(gain)

