import sys

def min_cost(k, a, p, b, q):
    if k <= 0:
        return 0
    INF = 10**30
    best = INF

    # For capacity a*b:
    #  - b units of machine S cost b*p
    #  - a units of machine T cost a*q
    # Keep only the cheaper block replacement in an optimal solution.
    if p * b <= q * a:
        # Assume y < a
        for y in range(a):
            rem = k - b * y
            if rem <= 0:
                x = 0
            else:
                x = (rem + a - 1) // a
            cost = x * p + y * q
            if cost < best:
                best = cost
    else:
        # Assume x < b
        for x in range(b):
            rem = k - a * x
            if rem <= 0:
                y = 0
            else:
                y = (rem + b - 1) // b
            cost = x * p + y * q
            if cost < best:
                best = cost

    return best


