from typing import *

MOD = 10**9 + 7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        L = len(s)

        # Binomial coefficients C[n][r] modulo MOD, for 0 <= n,r <= L.
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for n in range(L + 1):
            C[n][0] = 1
            C[n][n] = 1
            for r in range(1, n):
                C[n][r] = (C[n - 1][r - 1] + C[n - 1][r]) % MOD

        # g[t] = operations needed to reduce t to 1 via repeated popcount.
        # Only needed up to L (max possible popcount of any x < n).
        g = [0] * (L + 1)
        for t in range(2, L + 1):
            g[t] = 1 + g[t.bit_count()]

        def count_less_with_ones(target_ones: int) -> int:
            """Count numbers x in [0, n) whose L-bit form has exactly target_ones ones."""
            need = target_ones
            ans = 0
            for i, ch in enumerate(s):
                rem = L - 1 - i
                if ch == '1':
                    # Put 0 here (making prefix smaller), choose remaining ones freely.
                    if 0 <= need <= rem:
                        ans = (ans + C[rem][need]) % MOD
                    # Follow equal-prefix path: must put 1 here.
                    need -= 1
                    if need < 0:
                        break
            return ans

        ans = 0
        for ones in range(1, L + 1):
            # For x>1: steps = 1 + g[popcount(x)] = 1 + g[ones].
            # ones==1 includes x=1 as well (0 steps), and all powers of two (1 step).
            if ones == 1 or 1 + g[ones] <= k:
                ans = (ans + count_less_with_ones(ones)) % MOD

        return ans

