import sys

sys.setrecursionlimit(1_000_000)


def is_mountain(n: int) -> int:
    lsb = n & -n
    # Mountain iff odd part of n is 3 (mod 4)
    return 1 if (n & (lsb << 1)) != 0 else 0


def main() -> None:
    input = sys.stdin.readline
    N = int(input().strip())
    A = list(map(int, input().split()))

    MAXD = 100
    U = (1 << 100) - A[-1] - 1  # i upper bound from statement

    best = 0

    def feasible(res: int, d: int) -> bool:
        """Whether exists i in [1, U] with i ≡ res (mod 2^d)."""
        step = 1 << d
        if res > U:
            return False
        if res < 1:
            m = (1 - res + step - 1) // step
            v = res + m * step
        else:
            v = res
        return v <= U

    def dfs(res: int, d: int) -> None:
        nonlocal best

        if not feasible(res, d):
            return

        if d == MAXD:
            i = res
            if 1 <= i <= U:
                cnt = 0
                for a in A:
                    cnt += is_mountain(i + a)
                if cnt > best:
                    best = cnt
            return

        if d <= 1:
            decided_m = 0
            undec = N
        else:
            mask = (1 << d) - 1
            half = 1 << (d - 1)
            decided_m = 0
            undec = 0
            for a in A:
                x = (res + a) & mask
                # Undecidable at this depth iff v2(x) >= d-1, i.e. x is 0 or 2^(d-1) mod 2^d
                if x == 0 or x == half:
                    undec += 1
                else:
                    tz = (x & -x).bit_length() - 1
                    decided_m += 1 if ((x >> tz) & 3) == 3 else 0

        # Upper bound pruning
        if decided_m + undec <= best:
            return

        # If all positions are already decided, subtree value is fixed
        if undec == 0:
            if decided_m > best:
                best = decided_m
            return

        # Branch on next bit of i
        dfs(res, d + 1)
        dfs(res | (1 << d), d + 1)

    dfs(0, 0)
    print(best)


if __name__ == "__main__":
    main()

