import sys

def main() -> None:
    s = sys.stdin.readline().strip()
    n = len(s)

    # Manacher (odd lengths)
    d1 = [0] * n
    l, r = 0, -1
    for i in range(n):
        k = 1 if i > r else min(d1[l + r - i], r - i + 1)
        while i - k >= 0 and i + k < n and s[i - k] == s[i + k]:
            k += 1
        d1[i] = k
        if i + k - 1 > r:
            l = i - k + 1
            r = i + k - 1

    # Manacher (even lengths)
    d2 = [0] * n
    l, r = 0, -1
    for i in range(n):
        k = 0 if i > r else min(d2[l + r - i + 1], r - i + 1)
        while i - k - 1 >= 0 and i + k < n and s[i - k - 1] == s[i + k]:
            k += 1
        d2[i] = k
        if i + k - 1 > r:
            l = i - k
            r = i + k - 1

    longest_suffix_pal = 1  # n >= 1

    for i, k in enumerate(d1):
        # odd palindrome [i-k+1, i+k-1]
        if i + k - 1 == n - 1:
            length = 2 * k - 1
            if length > longest_suffix_pal:
                longest_suffix_pal = length

    for i, k in enumerate(d2):
        # even palindrome [i-k, i+k-1]
        if i + k - 1 == n - 1:
            length = 2 * k
            if length > longest_suffix_pal:
                longest_suffix_pal = length

    add = s[: n - longest_suffix_pal][::-1]
    print(s + add)

