def exists_bruteforce(N,edges):
    # brute over all assignments of N-bit labels with up to N bits is huge.
    # Use theorem: need subset of kernel vectors covering all coords.
    # brute verify by searching in span columns up to N? We'll brute all subsets of kernel vectors indeed.
    A=[0]*N
    for u,v in edges:
        A[u]|=1<<v;A[v]|=1<<u
    ker=[]
    for x in range(1<<N):
        ok=True
        for r in A:
            if ((r & x).bit_count()&1): ok=False;break
