    pf={}
    for p in pivot:
        m=rows[pr[p]] & ~(1<<p)
        for q in pivot:
            if q!=p: m&=~(1<<q)
        pf[p]=m
    for i in range(N):
        if isp[i] and pf[i]==0: return False
    return True

