import sys, math

def main():
    N = int(sys.stdin.readline().strip())

    # Since x^3 - y^3 = (y+d)^3 - y^3 > d^3 (for y>0), we always have d < cbrt(N) <= 10^6.
    for d in range(1, 10**6 + 1):
        if N % d != 0:
            continue

        M = N // d
        # From N = d * (3y^2 + 3dy + d^2):
        # 3y^2 + 3dy + (d^2 - M) = 0
        # Discriminant: Delta = (3d)^2 - 12(d^2 - M) = 12M - 3d^2
        delta = 12 * M - 3 * d * d
        if delta < 0:
            continue

        s = math.isqrt(delta)
        if s * s != delta:
            continue

        num = s - 3 * d
        if num <= 0 or num % 6 != 0:
            continue

        y = num // 6
        if y <= 0:
            continue

        x = y + d
        if x * x * x - y * y * y == N:
            print(x, y)
            return

    print(-1)

if __name__ == "__main__":
    main()

