from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        INF = 10**18

        # Factorials with saturation to avoid huge integers (k <= 1e15).
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            v = fact[i - 1] * i
            fact[i] = v if v < INF else INF

        used = [False] * (n + 1)
        odd_rem = (n + 1) // 2
        even_rem = n // 2
        ans = []

        for pos in range(n):
            chosen = -1
            prev_parity = ans[-1] & 1 if ans else -1

            # Try candidates in ascending order to build lexicographically.
            for cand in range(1, n + 1):
                if used[cand]:
                    continue
                p = cand & 1

                # Adjacent elements must have different parity.
                if pos > 0 and p == prev_parity:
                    continue

                o = odd_rem - (1 if p == 1 else 0)
                e = even_rem - (1 if p == 0 else 0)
                m = n - pos - 1  # remaining length after fixing cand

                if m == 0:
                    cnt = 1
                else:
                    # Next parity must alternate.
                    next_parity = 1 - p
                    odd_need = (m + 1) // 2 if next_parity == 1 else m // 2
                    even_need = m - odd_need

                    if o == odd_need and e == even_need:
                        cnt = fact[o] * fact[e]
                        if cnt > INF:
                            cnt = INF
                    else:
                        cnt = 0

                if k > cnt:
                    k -= cnt
                else:
                    chosen = cand
                    break

            if chosen == -1:
                return []

            ans.append(chosen)
            used[chosen] = True
            if chosen & 1:
                odd_rem -= 1
            else:
                even_rem -= 1

        return ans

