def model(A,B,C):
 D=[C[i] for i in range(len(A)) if A[i]==1 and B[i]==0]
 U=[C[i] for i in range(len(A)) if A[i]==0 and B[i]==1]
 E=[C[i] for i in range(len(A)) if A[i]==1 and B[i]==1]
 S0=sum(A[i]*C[i] for i in range(len(A)))
 best=10**18
 mE=len(E)
 for mask in range(1<<mE):
  ds=[]
  for c in D: ds.append(-c)
  for c in U: ds.append(c)
  for j,c in enumerate(E):
   if mask>>j &1:
    ds.append(-c);ds.append(c)
  ds.sort()
  m=len(ds)
  val=m*S0+sum(d*(m-i) for i,d in enumerate(ds))
  best=min(best,val)
 return best

