class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        # pow10[i] = 10^i mod k
        pow10 = [0] * n
        pow10[0] = 1 % k
        for i in range(1, n):
            pow10[i] = (pow10[i - 1] * 10) % k

        # Contribution (mod k) of choosing digit d at left-half index i
        # (mirrored position contributes too, except the middle when n is odd)
        w = [0] * m
        for i in range(m):
            j = n - 1 - i
            if i == j:
                w[i] = pow10[i]
            else:
                w[i] = (pow10[i] + pow10[j]) % k

        # feasible[i][r] = using positions i..m-1, can we obtain remainder r?
        feasible = [[False] * k for _ in range(m + 1)]
        feasible[m][0] = True

        for i in range(m - 1, -1, -1):
            wi = w[i]
            nxt = feasible[i + 1]
            row = feasible[i]
            for r in range(k):
                ok = False
                for d in range(10):
                    if nxt[(r - d * wi) % k]:
                        ok = True
                        break
                row[r] = ok

        # Greedily build the largest left half
        left = []
        pref = 0  # remainder contributed by chosen prefix of left half

        for i in range(m):
            wi = w[i]
            low = 1 if i == 0 else 0  # no leading zero
            chosen = -1
            for d in range(9, low - 1, -1):
                need = (-pref - d * wi) % k
                if feasible[i + 1][need]:
                    chosen = d
                    break

            left.append(str(chosen))
            pref = (pref + chosen * wi) % k

        # Mirror to form the full palindrome
        if n % 2 == 0:
            return ''.join(left + left[::-1])
        return ''.join(left + left[:-1][::-1])

