import random

def fast(nums,k):
    n=len(nums)
    blocks=deque() # (val,len)
    j=n-1
    cost=0
    ans=0
    for i in range(n-1,-1,-1):
        blocks.appendleft([nums[i],1])
        while len(blocks)>=2 and blocks[1][0] < blocks[0][0]:
            v0,l0=blocks[0]
            v1,l1=blocks[1]
            cost += (v0-v1)*l1
            blocks[0]=[v0,l0+l1]
            blocks.remove(blocks[1])
        while cost>k:
            v,l=blocks[-1]
            cost -= v-nums[j]
            if l==1:
                blocks.pop()
            else:
                blocks[-1]=[v,l-1]
            j-=1
        ans += j-i+1
    return ans

def brute(nums,k):
    n=len(nums)
    ans=0
    for l in range(n):
        m=0
        for r in range(l,n):
            if r==l:
                m=nums[l];cost=0
            else:
                if nums[r]>=m:
                    m=nums[r]
