import random,itertools,math

def solve(N,K,arr):
    L=1
    for d in range(1,51):L=math.lcm(L,d)
    funcs=[]
    for A,B in arr:
        funcs.append((((A-1)*L)//B,A,B))
    funcs.sort(key=lambda x:x[0],reverse=True)
    NEG=-10**100
    dp=[NEG]*(K+1);dp[0]=1
    for _,A,B in reversed(funcs):
        for j in range(K,0,-1):
            if dp[j-1]!=NEG:
                dp[j]=max(dp[j],A*dp[j-1]+B)
    return dp[K]

