import sys

def main() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, K = data[0], data[1]
    A = data[2:2 + N]

    total_xor = 0
    for v in A:
        total_xor ^= v

    if K == N:
        print(total_xor)
        return

    # Enumerate the smaller side:
    # - if K is small, enumerate chosen subsets directly
    # - otherwise enumerate omitted subsets of size N-K
    direct = (K <= N - K)
    m = K if direct else (N - K)

    if m == 0:
        print(total_xor)
        return

    # First combination: [0,1,...,m-1]
    idx = list(range(m))
    cur_xor = 0
    for i in idx:
        cur_xor ^= A[i]

    if direct:
        ans = cur_xor
    else:
        ans = total_xor ^ cur_xor

    # Iterate all combinations of size m in lexicographic order
    while True:
        t = m - 1
        while t >= 0 and idx[t] == t + N - m:
            t -= 1
        if t < 0:
            break

        # Remove old suffix contribution
        for j in range(t, m):
            cur_xor ^= A[idx[j]]

        # Move to next combination
        idx[t] += 1
        for j in range(t + 1, m):
            idx[j] = idx[j - 1] + 1

        # Add new suffix contribution
        for j in range(t, m):
            cur_xor ^= A[idx[j]]

        if direct:
            if cur_xor > ans:
                ans = cur_xor
        else:
            val = total_xor ^ cur_xor
            if val > ans:
                ans = val

    print(ans)

if __name__ == "__main__":
    main()

