import sys

class Fenwick:
    def __init__(self, n: int):
        self.n = n
        self.bit = [0] * (n + 1)

    def build_all_ones(self):
        n = self.n
        bit = self.bit
        for i in range(1, n + 1):
            bit[i] += 1
            j = i + (i & -i)
            if j <= n:
                bit[j] += bit[i]

    def add(self, i: int, x: int):
        n = self.n
        bit = self.bit
        while i <= n:
            bit[i] += x
            i += i & -i

    def lower_bound(self, k: int) -> int:
        idx = 0
        bitmask = 1 << (self.n.bit_length() - 1)
        bit = self.bit
        while bitmask:
            nxt = idx + bitmask
            if nxt <= self.n and bit[nxt] < k:
                k -= bit[nxt]
                idx = nxt
            bitmask >>= 1
        return idx + 1


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    p = data[1:1 + n]

    fw = Fenwick(n)
    fw.build_all_ones()

    ans = [0] * (n + 1)  # 1-indexed positions

    for i in range(n, 0, -1):
        pos = fw.lower_bound(p[i - 1])
        ans[pos] = i
        fw.add(pos, -1)

    print(*ans[1:])


