import random

def fast(A,B):
    n=len(A)
    a=A[0]
    b=B[0]
    c=0
    for i in range(1,n):
        na=max(a,c)+A[i]
        nb=max(b,c)+B[i]
        nc=max(a,b,c)
        a,b,c=na,nb,nc
    return max(a,b,c)

def brute(A,B):
    n=len(A)
    # dp over actions 0:A 1:B 2:C
    NEG=-10**18
    dp=[NEG,NEG,0]
    for i in range(n):
        ndp=[NEG,NEG,NEG]
        for prev in range(3):
            cur=dp[prev]
            if cur<0 and not (i==0 and prev==2):
                pass
            # choose C always
            ndp[2]=max(ndp[2],cur)
            # choose A allowed if prev!=1
            if prev!=1:
                ndp[0]=max(ndp[0],cur+A[i])
            # choose B allowed if prev!=0
            if prev!=0:
                ndp[1]=max(ndp[1],cur+B[i])
        dp=ndp
    return max(dp)

for n in range(3,9):
    for _ in range(5000):
        A=[random.randint(1,9) for _ in range(n)]
        B=[random.randint(1,9) for _ in range(n)]
        f=fast(A,B)
        g=brute(A,B)
        if f!=g:
            print('mismatch',n,A,B,f,g)
            raise SystemExit
print('ok')

