import random

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        INF = 10**30
        min_pref = [INF] * k
        min_pref[0] = 0
        pref = 0
        ans = -INF
        for j, x in enumerate(nums, 1):
            pref += x
            r = j % k
            if min_pref[r] != INF:
                ans = max(ans, pref - min_pref[r])
            if pref < min_pref[r]:
                min_pref[r] = pref
        return ans

def brute(nums,k):
    n=len(nums)
    best=-10**30
    for i in range(n):
        s=0
        for j in range(i,n):
            s+=nums[j]
            if (j-i+1)%k==0:
                best=max(best,s)
    return best

# given examples
print(Solution().maxSubarraySum([1,2],1))
print(Solution().maxSubarraySum([-1,-2,-3,-4,-5],4))
print(Solution().maxSubarraySum([-5,1,2,-3,4],2))

for n in range(1,25):
    for k in range(1,n+1):
        for _ in range(200):
            nums=[random.randint(-9,9) for _ in range(n)]
            a=Solution().maxSubarraySum(nums,k)
            b=brute(nums,k)
            if a!=b:
                print('mismatch',n,k,nums,a,b)
                raise SystemExit
