from typing import List
from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def lcm(a: int, b: int) -> int:
            return a // gcd(a, b) * b

        def factor_score(arr: List[int]) -> int:
            if not arr:
                return 0
            g = arr[0]
            l = arr[0]
            for x in arr[1:]:
                g = gcd(g, x)
                l = lcm(l, x)
            return g * l

        n = len(nums)
        best = factor_score(nums)  # no removal

        for i in range(n):
            best = max(best, factor_score(nums[:i] + nums[i + 1:]))

        return best

