import sys, math

def sieve(n: int):
    if n < 2:
        return []
    is_prime = bytearray(b'\x01') * (n + 1)
    is_prime[0:2] = b'\x00\x00'
    r = int(n ** 0.5)
    for i in range(2, r + 1):
        if is_prime[i]:
            start = i * i
            is_prime[start:n + 1:i] = b'\x00' * (((n - start) // i) + 1)
    return [i for i in range(2, n + 1) if is_prime[i]]


def main():
    N = int(sys.stdin.readline())

    # For numbers of form p^2 q^2, we need pq <= sqrt(N)
    M = math.isqrt(N)
    primes = sieve(M)

    # 1) n = p^8
    count_p8 = 0
    for p in primes:
        if p ** 8 <= N:
            count_p8 += 1
        else:
            break

    # 2) n = p^2 q^2 (p < q), equivalent to pq <= sqrt(N)
    count_pairs = 0
    j = len(primes) - 1
    for i, p in enumerate(primes):
        while j > i and p * primes[j] > M:
            j -= 1
        if j <= i:
            break
        count_pairs += (j - i)

    print(count_p8 + count_pairs)


if __name__ == "__main__":
    main()

