from typing import List

class Line:
    __slots__ = ("m", "b")

    def __init__(self, m: int, b: int):
        self.m = m
        self.b = b

    def val(self, x: int) -> int:
        return self.m * x + self.b


class Node:
    __slots__ = ("line", "left", "right")

    def __init__(self, line: Line):
        self.line = line
        self.left = None
        self.right = None


class LiChaoTree:
    def __init__(self, xl: int, xr: int):
        self.xl = xl
        self.xr = xr
        self.root = None

    def insert_line(self, m: int, b: int) -> None:
        new_line = Line(m, b)
        if self.root is None:
            self.root = Node(new_line)
            return
        self._insert(self.root, self.xl, self.xr, new_line)

    def _insert(self, node: Node, l: int, r: int, line: Line) -> None:
        mid = (l + r) // 2
        cur = node.line

        if line.val(mid) > cur.val(mid):
            node.line, line = line, node.line
            cur = node.line

        if l == r:
            return

        if line.val(l) > cur.val(l):
            if node.left is None:
                node.left = Node(line)
            else:
                self._insert(node.left, l, mid, line)
        elif line.val(r) > cur.val(r):
            if node.right is None:
                node.right = Node(line)
            else:
                self._insert(node.right, mid + 1, r, line)

    def query(self, x: int) -> int:
        return self._query(self.root, self.xl, self.xr, x)

    def _query(self, node: Node, l: int, r: int, x: int) -> int:
        if node is None:
            return -10**30

        ans = node.line.val(x)
        if l == r:
            return ans

        mid = (l + r) // 2
        if x <= mid:
            child = self._query(node.left, l, mid, x)
        else:
            child = self._query(node.right, mid + 1, r, x)
        return ans if ans > child else child


class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        tree = LiChaoTree(0, n - 1)

        # dp[0] = 0 -> line: y = nums[0] * x + (0 - 0 * nums[0])
        tree.insert_line(nums[0], 0)
        dp_j = 0

        for j in range(1, n):
            dp_j = tree.query(j)
            # Add state j for future transitions.
            tree.insert_line(nums[j], dp_j - j * nums[j])

        return dp_j

