class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        cnt = Counter(nums)

        best = -10**30

        # Try each value as the "sum of special numbers" element.
        for s, count_s in cnt.items():
            outlier = total - 2 * s

            count_o = cnt.get(outlier, 0)
            if count_o == 0:
                continue

            # Need distinct indices for sum element and outlier.
            if outlier != s or count_s >= 2:
                if outlier > best:
                    best = outlier

        return best

