from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        # k can be 0 (use no query)
        if all(x == 0 for x in nums):
            return 0

        max_need = max(nums)
        mask = (1 << (max_need + 1)) - 1

        # reachable[i]: bit s is 1 iff sum s can be formed for index i
        # using the processed prefix of queries that cover i.
        reachable = [1] * n  # only sum 0 initially

        for k, (l, r, val) in enumerate(queries, start=1):
            for i in range(l, r + 1):
                reachable[i] = (reachable[i] | (reachable[i] << val)) & mask

            ok = True
            for i, need in enumerate(nums):
                if ((reachable[i] >> need) & 1) == 0:
                    ok = False
                    break
            if ok:
                return k

        return -1

