from heapq import heappush, heappop

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        sn, sm = str(n), str(m)
        d = len(sn)
        if len(sm) != d:
            return -1

        limit = 10 ** d

        # Prime sieve on [0, limit)
        is_prime = [True] * limit
        if limit > 0:
            is_prime[0] = False
        if limit > 1:
            is_prime[1] = False
        p = 2
        while p * p < limit:
            if is_prime[p]:
                start = p * p
                is_prime[start:limit:p] = [False] * (((limit - 1 - start) // p) + 1)
            p += 1

        # n and m themselves must be non-prime
        if is_prime[n] or is_prime[m]:
            return -1

        # Keep the same digit count during the process (no leading zero for d>1)
        lo = 0 if d == 1 else 10 ** (d - 1)

        INF = 10**30
        dist = [INF] * limit
        dist[n] = n  # cost includes the initial value
        pq = [(n, n)]  # (cost, value)

        while pq:
            cost, x = heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            s = list(str(x))
            if len(s) < d:
                s = ['0'] * (d - len(s)) + s

            for i, ch in enumerate(s):
                digit = ord(ch) - 48

                # Increase this digit
                if digit < 9:
                    s[i] = chr(ord(ch) + 1)
                    y = int(''.join(s))
                    if y >= lo and not is_prime[y]:
                        new_cost = cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heappush(pq, (new_cost, y))
                    s[i] = ch

                # Decrease this digit
                if digit > 0:
                    s[i] = chr(ord(ch) - 1)
                    y = int(''.join(s))
                    if y >= lo and not is_prime[y]:
                        new_cost = cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heappush(pq, (new_cost, y))
                    s[i] = ch

        return -1

