class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        def z_function(a: List[int]) -> List[int]:
            m = len(a)
            z = [0] * m
            l = r = 0
            for i in range(1, m):
                if i <= r:
                    z[i] = min(r - i + 1, z[i - l])
                while i + z[i] < m and a[z[i]] == a[i + z[i]]:
                    z[i] += 1
                if i + z[i] - 1 > r:
                    l, r = i, i + z[i] - 1
            return z

        # z0[i] = LCP(nums[0:], nums[i:])
        z0 = z_function(nums)

        # Count splits where nums1 is a prefix of nums2.
        # i = end of nums1, j = end of nums2
        # Condition depends on i only, then all j >= 2i are valid.
        pref_ok = [False] * n
        cond1 = 0
        for i in range(1, n - 1):
            if z0[i] >= i:
                pref_ok[i] = True
                add = n - 2 * i  # number of j in [2i, n-1]
                if add > 0:
                    cond1 += add

        # Count splits where nums2 is a prefix of nums3.
        # Also count overlap with cond1 for inclusion-exclusion.
        cond2 = 0
        overlap = 0
        for i in range(1, n - 1):
            suf = nums[i:]
            z = z_function(suf)
