import sys

def within_one_edit(s: str, t: str) -> bool:
    ls, lt = len(s), len(t)
    if abs(ls - lt) > 1:
        return False

    if ls == lt:
        mism = 0
        for a, b in zip(s, t):
            if a != b:
                mism += 1
                if mism > 1:
                    return False
        return True

    # Ensure s is shorter, t is longer
    if ls > lt:
        s, t = t, s
        ls, lt = lt, ls

    i = j = 0
    skipped = False
    while i < ls and j < lt:
        if s[i] == t[j]:
            i += 1
            j += 1
        else:
            if skipped:
                return False
            skipped = True
            j += 1  # skip one character in longer string

    return True


