    data = sys.stdin.read().splitlines()
    if not data:
        return
    k = int(data[0].strip())
    s = data[1].strip()
    t = data[2].strip()

    if k == 0:
        print("Yes" if s == t else "No")
        return

    print("Yes" if within_one_edit(s, t) else "No")


