class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)

        # Mark removable positions.
        is_target = [0] * n
        for idx in targetIndices:
            is_target[idx] = 1

        # dp[j] = minimum number of target indices used to match pattern[:j]
        # as a subsequence in the processed prefix of source.
        INF = 10**9
        dp = [INF] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = is_target[i]  # 1 if using this char consumes a removable index, else 0
            for j in range(m, 0, -1):
                if ch == pattern[j - 1] and dp[j - 1] != INF:
                    cand = dp[j - 1] + cost
                    if cand < dp[j]:
                        dp[j] = cand

        # Keep as few target indices as necessary; remove the rest.
        return len(targetIndices) - dp[m]

