import sys

def main():
    input = sys.stdin.readline
    N, W = map(int, input().split())

    cols = [[] for _ in range(W + 1)]
    for i in range(1, N + 1):
        x, y = map(int, input().split())
        cols[x].append((y, i))

    # Sort each column by height and compute rank of each block in its column.
    rank = [0] * (N + 1)
    counts = [0] * (W + 1)
    for x in range(1, W + 1):
        cols[x].sort()
        counts[x] = len(cols[x])
        for r, (y, i) in enumerate(cols[x], start=1):
            rank[i] = r

    M = min(counts[1:]) if W > 0 else 0

    INF = 10**30
    death = [INF] * (N + 1)

    if M > 0:
        clear_time = [0] * (M + 1)  # 1-indexed
        # r-th clear time = max over columns of y_{x,r}
        for x in range(1, W + 1):
            col = cols[x]
            for r in range(1, M + 1):
                y, _ = col[r - 1]
                if y > clear_time[r]:
                    clear_time[r] = y

        for i in range(1, N + 1):
            r = rank[i]
            if r <= M:
                death[i] = clear_time[r]

    Q = int(input())
    out = []
    for _ in range(Q):
        T, A = map(int, input().split())
        out.append("Yes" if death[A] > T else "No")

    print("\n".join(out))

if __name__ == "__main__":
    main()

