class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a', 'e', 'i', 'o', 'u'}

        def at_most(K: int) -> int:
            if K < 0:
                return 0

            last = {v: -1 for v in vowels}
            l = 0
            consonants = 0
            total = 0

            for r, ch in enumerate(word):
                if ch in vowels:
                    last[ch] = r
                else:
                    consonants += 1

                while consonants > K:
                    if word[l] not in vowels:
                        consonants -= 1
                    l += 1

                min_last_vowel = min(last.values())
                if min_last_vowel >= l:
                    total += min_last_vowel - l + 1

            return total

        return at_most(k) - at_most(k - 1)

