class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a', 'e', 'i', 'o', 'u'}

        def at_most(K: int) -> int:
            if K < 0:
                return 0
            last = {v: -1 for v in vowels}
            l = 0
            cons = 0
            total = 0
            for r, ch in enumerate(word):
                if ch in vowels:
                    last[ch] = r
                else:
                    cons += 1

                while cons > K:
                    if word[l] not in vowels:
                        cons -= 1
                    l += 1

                m = min(last.values())
                if m >= l:
                    total += (m - l + 1)
            return total

        return at_most(k) - at_most(k - 1)

