from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = {(x, y) for x, y in points}
        n = len(points)
        best = -1

        for i in range(n):
            x1, y1 = points[i]
            for j in range(i + 1, n):
                x2, y2 = points[j]

                # Need a diagonal of a non-degenerate axis-aligned rectangle.
                if x1 == x2 or y1 == y2:
                    continue

                # The other two corners must exist.
                if (x1, y2) not in point_set or (x2, y1) not in point_set:
                    continue

                left, right = (x1, x2) if x1 < x2 else (x2, x1)
                bottom, top = (y1, y2) if y1 < y2 else (y2, y1)
                corners = {(left, bottom), (left, top), (right, bottom), (right, top)}

                # No other point may lie inside or on border.
                valid = True
                for x, y in points:
                    if (x, y) in corners:
                        continue
                    if left <= x <= right and bottom <= y <= top:
                        valid = False
                        break

                if valid:
                    area = (right - left) * (top - bottom)
                    if area > best:
                        best = area

        return best

